"""Consolidate existing effect dossiers without upgrading documentary certainty."""
import hashlib,json,shutil
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];d=ROOT/'documentos';path=ROOT/'static/corpus.json'
c=json.loads(path.read_text());by={r['id']:r for r in c['records']};records=[r for r in c['records'] if r['source']=='digesto'];effects={e['source']:e for e in c['normativeEffects']}
assert len(records)==398 and len(effects)==398 and set(effects)=={r['id'] for r in records}
for r in records:
 e=effects[r['id']]
 assert hashlib.sha256(r['textOriginal'].encode()).hexdigest()==e['sourceHash'],r['id']
 assert hashlib.sha256(r['textEs'].encode()).hexdigest()==e['translationHash'],r['id']
 assert e['sourcePDFSHA256']==c['metadata']['sources']['digesto']['sha256'],r['id']
 for target in e['targets']:
  if target.startswith(('CI-art-','CD-art-','RI-CE-art-','ATAS-art-')):assert target in by,target
progress={'date':'2026-10-14','consolidatedDecisions':398,'totalDecisions':398,'supplementComplete':True,'editorialFinalReviewComplete':False,'externalCertification':False,'officialSpanishApproval':False,'scope':'Consolidación de los efectos examinados; control de coherencia de informes y trazabilidad. No acredita ejecución posterior ni compatibilidad definitiva de todas las notas históricas.','documents':['suplemento_normativo_2026_es.md','suplemento_normativo_2026_pt.md','revision_editorial_consolidacion_2026_es.md','revision_editorial_consolidacion_2026_pt.md']}
c['metadata']['editorialConsolidationProgress']=progress
issues=[
 ('SC-2026-CLXXXV','Falta la propuesta integral de los reglamentos de seminarios y la base RI-JET. Se conservan los 29 ajustes aprobados y la transición a 2030.','Faltam a proposta integral dos regimentos dos seminários e a base RI-JET. Conservados os 29 ajustes aprovados e a transição para 2030.'),
 ('CE-2026-CXXXV','Referencias LXXIII y LXXXIII distintas en la misma decisión; no se unifican silenciosamente.','Referências LXXIII e LXXXIII distintas na mesma decisão; não são unificadas silenciosamente.'),
 ('CE-2026-LXXXIII','No consta la base íntegra del estatuto Erasmo Braga; conservar las alteraciones y sus límites documentales.','Não consta a base integral do estatuto Erasmo Braga; conservar as alterações e seus limites documentais.'),
 ('CE-2026-CXLI','IBN: discrepancia del artículo 4 entre resolución y texto consolidado; registro y publicación condicionados sin ejecución acreditada.','IBN: discrepância do artigo 4 entre resolução e texto consolidado; registro e publicação condicionados sem execução comprovada.'),
 ('CE-2026-LXXXVI','Siglas PRCV/PRER distintas de PBCV/PBER en CE-XCVIII; no presumir identidad sin confirmar.','Siglas PRCV/PRER distintas de PBCV/PBER em CE-XCVIII; não presumir identidade sem confirmar.'),
 ('CE-2026-XII','Nacimiento 17.03.1978 y ordenación 08.01.1989: fechas de la fuente conservadas y pendientes de confirmación.','Nascimento 17.03.1978 e ordenação 08.01.1989: datas da fonte conservadas e pendentes de confirmação.'),
 ('CE-2026-VII','Cavalcante/Cavalcanti entre restauración y baja de CE-V: no fusionar identidades ni deducir una secuencia de efectos.','Cavalcante/Cavalcanti entre restauração e baixa de CE-V: não fundir identidades nem deduzir uma sequência de efeitos.'),
 ('CE-2026-XLIV','Referencia a 70 años junto a fecha de nacimiento de 1965; conservar la divergencia y confirmar documentalmente.','Referência a 70 anos junto à data de nascimento de 1965; conservar a divergência e confirmar documentalmente.'),
 ('SC-2026-CIX','Antecedente revocado por CE-CXIX. Se conserva para trazabilidad y no se presenta como decisión operativa vigente.','Antecedente revogado por CE-CXIX. Conservado para rastreabilidade e não apresentado como decisão operativa vigente.')]
for rid,_,_ in issues:assert rid in by
review=json.loads((d/'auditoria_revision_manual.json').read_text());flagreviews=[]
for f in review['candidates']:
 assert f['terms']==['São'],f
 text=by[f['id']]['textEs'];positions=[];start=0
 while (i:=text.find('São',start))>=0:
  positions.append(text[max(0,i-45):i+85]);start=i+3
 assert positions,f['id']
 flagreviews.append({**f,'classification':'proper-name-preserved','reviewDate':'2026-10-14','contexts':positions,'scope':'Señal São únicamente; no certifica la redacción completa de la unidad.'})
assert len(flagreviews)==9
for lang in ['es','pt']:
 es=lang=='es';title='Suplemento normativo 2026' if es else 'Suplemento normativo 2026'
 parts=[f'# {title}\n\n',('> Edición de trabajo no oficial. 398/398 decisiones traducidas, cotejadas y examinadas por sus efectos. Consolidación documental del 14 de octubre de 2026. Revisión editorial definitiva y aprobación oficial pendientes.\n\n' if es else '> Edição de trabalho não oficial. 398/398 decisões traduzidas, conferidas e examinadas quanto aos efeitos. Consolidação documental de 14 de outubro de 2026. Aprovação editorial definitiva e oficial pendentes.\n\n'),('Este suplemento reúne los efectos de los 21 lotes, por el orden del Digesto, separado del Manual histórico de 2025. Las seis enmiendas constitucionales, la revocación del inciso X del art. 8 del RI-CE y la sustitución del caput del art. 3 de Actas permanecen en el Manual integrado. Las demás decisiones se conservan como apuntes con su alcance y límites. Los 21 informes históricos conservan las cifras correspondientes a su fecha de entrega.\n\n' if es else 'Este suplemento reúne os efeitos dos 21 lotes, pela ordem do Digesto, separado do Manual histórico de 2025. As seis emendas constitucionais, a revogação do inciso X do art. 8 do RI-CE e a substituição do caput do art. 3 de Atas permanecem no Manual integrado. As demais decisões ficam como apontamentos com seu alcance e limites. Os 21 relatórios históricos conservam os números de sua data de entrega.\n\n'),'## Índice\n\n',('| Decisión | Remisiones | Estado documental |\n| --- | --- | --- |\n' if es else '| Decisão | Remissões | Situação documental |\n| --- | --- | --- |\n')]
 for r in records:
  e=effects[r['id']];state=('Revocada por CE-2026-CXIX' if es else 'Revogada por CE-2026-CXIX') if r['id']=='SC-2026-CIX' else ('Examinada; ver alcance y límites' if es else 'Examinada; ver alcance e limites')
  parts.append(f"| [{r['id']}](#{r['id']}) | {', '.join(e['targets']) or ('Apuntes' if es else 'Apontamentos')} | {state} |\n")
 for r in records:
  e=effects[r['id']];parts.append(f'\n<a id="{r["id"]}"></a>\n\n## {r["id"]}\n\nPDF: '+', '.join(map(str,e['pages']))+'\n\n')
  if r['id']=='SC-2026-CIX':parts.append('**'+('Antecedente revocado por CE-2026-CXIX.' if es else 'Antecedente revogado por CE-2026-CXIX.')+'**\n\n')
  parts.append(('### Alcance\n\n' if es else '### Alcance\n\n')+e['noteEs' if es else 'notePt']+'\n\n### '+('Límites' if es else 'Limites')+'\n\n'+e['limitsEs' if es else 'limitsPt']+'\n\n')
  parts.append(('Remisiones: ' if es else 'Remissões: ')+(', '.join(e['targets']) or ('Apuntes separados' if es else 'Apontamentos separados'))+'\n\n')
  if e.get('regulatoryAdjustments'):
   parts.append('### '+('Ajustes aprobados a–cc' if es else 'Ajustes aprovados a–cc')+'\n\n')
   for a in e['regulatoryAdjustments']:parts.append('#### '+a['marker']+'\n\n'+a['textEs' if es else 'textPt']+'\n\n')
  parts.append('### '+('Evidencia — original portugués' if es else 'Evidência — original português')+'\n\n'+e['evidencePt']+'\n\n### '+('Decisión completa — español cotejado' if es else 'Decisão completa — português original')+'\n\n'+r['textEs' if es else 'textOriginal']+'\n\n')
  parts.append('SHA-256 PDF: `'+e['sourcePDFSHA256']+'`\n\nSHA-256 original: `'+e['sourceHash']+'`\n\nSHA-256 ES: `'+e['translationHash']+'`\n\n')
 (d/f'suplemento_normativo_2026_{lang}.md').write_text(''.join(parts))
 report='# '+('Revisión editorial y consolidación' if es else 'Revisão editorial e consolidação')+' — 14 de octubre / outubro de 2026\n\n'
 report+=('Consolidación documental completada. Revisión editorial definitiva pendiente; sin aprobación oficial ni certificación externa.\n\n' if es else 'Consolidação documental concluída. Aprovação editorial definitiva pendente; sem aprovação oficial nem certificação externa.\n\n')
 report+='| '+('Control | Resultado' if es else 'Controle | Resultado')+' |\n| --- | --- |\n| Manual 2025 | 1774/1774 |\n| '+('Anexo por páginas' if es else 'Anexo por páginas')+' | 560/560 |\n| Digesto 2026 | 398/398 |\n| '+('Efectos examinados y consolidados' if es else 'Efeitos examinados e consolidados')+' | 398/398 |\n| '+('Lotes históricos conservados' if es else 'Lotes históricos conservados')+' | 21 |\n\n'
 report+=('## Correcciones de esta entrega\n\n- Informes actuales actualizados: ya no indican 260 traducciones ni un anexo sin revisar.\n- CI, nota 259: «interesados e interesados» corregido a «interesados e involucrados», con el verbo y las gestiones recuperados del portugués. La página 118 del anexo ya expresa ese sentido y se conserva. Cambio registrado con hashes antes y después.\n- Las nueve señales automáticas «São» son nombres propios y se conservan; esta clasificación no aprueba todo el texto de esas unidades.\n- Suplemento por idioma con índice, decisión completa, efecto, límites, páginas y hashes. SC-CIX se marca como antecedente revocado.\n\n' if es else '## Correções desta entrega\n\n- Relatórios atuais atualizados: já não indicam 260 traduções nem anexo sem revisão.\n- CI, nota 259: «interesados e interesados» corrigido para «interesados e involucrados», recuperando o verbo e as gestões do português. A página 118 do anexo já expressa esse sentido e é conservada. Alteração registrada com hashes antes e depois.\n- As nove sinalizações automáticas «São» são nomes próprios e são conservadas; esta classificação não aprova todo o texto dessas unidades.\n- Suplemento por idioma com índice, decisão integral, efeito, limites, páginas e hashes. SC-CIX marcado como antecedente revogado.\n\n')
 report+='## '+('Pendientes documentales seleccionados' if es else 'Pendências documentais selecionadas')+'\n\n'+('Esta lista prioriza incidencias ya registradas; no constituye un inventario exhaustivo de dudas ni acredita ejecución posterior. Las fuentes se conservan sin corregir sus fechas, nombres o siglas por conjetura.\n\n' if es else 'Esta lista prioriza incidências já registradas; não constitui inventário exaustivo de dúvidas nem comprova execução posterior. As fontes são conservadas sem corrigir datas, nomes ou siglas por conjectura.\n\n')
 for rid,note_es,note_pt in issues:report+='- **'+rid+'**: '+(note_es if es else note_pt)+'\n'
 if c['metadata'].get('historicalCompatibilityProgress'):
  report+='\n## '+('Compatibilidad directa revisada' if es else 'Compatibilidade direta conferida')+'\n\n'+('8/8 artículos modificados, 25/25 notas directas y dos disposiciones relacionadas. Advertencias por pasaje registradas en [compatibilidad_notas_historicas_2026_es.md](compatibilidad_notas_historicas_2026_es.md). La clasificación del rastreo transversal está concluida; la confirmación de las divergencias sigue pendiente.\n' if es else '8/8 artigos alterados, 25/25 notas diretas e duas disposições relacionadas. Advertências por passagem registradas em [compatibilidad_notas_historicas_2026_pt.md](compatibilidad_notas_historicas_2026_pt.md). A classificação do rastreio transversal está concluída; a confirmação das divergências permanece pendente.\n')
 if c['metadata'].get('crossHistoricalCompatibilityProgress'):
  cross=c['metadata']['crossHistoricalCompatibilityProgress'];report+='\n## '+('Estado transversal actual' if es else 'Situação transversal atual')+'\n\n'+(f"Rastreo de {cross['notesScanned']} notas: {cross['candidateNotes']} candidatas automáticas, {cross.get('comparedReformRelatedNotes', cross['reviewedCandidateNotes'])} examinadas por su relación con reformas, {cross.get('excludedOtherReferenceNotes',0)} identificadas como otros dispositivos y {cross['pendingCandidateNotes']} pendientes de clasificación. Una candidata no es una incompatibilidad confirmada. Véase [compatibilidad_transversal_lote_01_2026_es.md](compatibilidad_transversal_lote_01_2026_es.md).\n" if es else f"Rastreio de {cross['notesScanned']} notas: {cross['candidateNotes']} candidatas automáticas, {cross.get('comparedReformRelatedNotes', cross['reviewedCandidateNotes'])} conferidas na relação com alterações, {cross.get('excludedOtherReferenceNotes',0)} identificadas como outros dispositivos e {cross['pendingCandidateNotes']} pendentes de classificação. Candidata não é incompatibilidade confirmada. Consulte [compatibilidad_transversal_lote_01_2026_pt.md](compatibilidad_transversal_lote_01_2026_pt.md).\n")
 if c['metadata'].get('crossHistoricalCompatibilityProgress',{}).get('excludedOtherReferenceNotes'):
  cross=c['metadata']['crossHistoricalCompatibilityProgress'];report+='\n## '+('Segundo lote transversal' if es else 'Segundo lote transversal')+'\n\n'+('40 referencias identificadas como menciones a otros dispositivos. Avance al cierre de ese lote: 60 candidatas clasificadas; entonces quedaban 82 pendientes. Véase [compatibilidad_transversal_lote_02_2026_es.md](compatibilidad_transversal_lote_02_2026_es.md). La clasificación no certifica vigencia general.\n' if es else '40 referências identificadas como menções a outros dispositivos. Avanço ao final desse lote: 60 candidatas classificadas; então restavam 82 pendentes. Consulte [compatibilidad_transversal_lote_02_2026_pt.md](compatibilidad_transversal_lote_02_2026_pt.md). A classificação não certifica vigência geral.\n')
 if c['metadata'].get('crossHistoricalCompatibilityProgress',{}).get('comparedReformRelatedNotes',0)>20:
  report+='\n## '+('Tercer lote transversal' if es else 'Terceiro lote transversal')+'\n\n'+('30 notas adicionales sobre competencias, representación y aclaraciones posteriores. Avance al cierre de ese lote: 90/142 candidatas; entonces quedaban 52 pendientes. Leer [compatibilidad_transversal_lote_03_2026_es.md](compatibilidad_transversal_lote_03_2026_es.md). Compatibilidad de CI49 §5 y CI27 requiere confirmación cuando el jubilado no es representante.\n' if es else '30 notas adicionais sobre competências, representação e esclarecimentos posteriores. Avanço ao final desse lote: 90/142 candidatas; então restavam 52 pendentes. Consulte [compatibilidad_transversal_lote_03_2026_pt.md](compatibilidad_transversal_lote_03_2026_pt.md). Compatibilidade de CI49 §5 e CI27 exige confirmação quando o jubilado não é representante.\n')
 if c['metadata'].get('crossHistoricalCompatibilityProgress',{}).get('comparedReformRelatedNotes',0)>50:
  report+='\n## '+('Cuarto lote transversal' if es else 'Quarto lote transversal')+'\n\n'+('24 notas de Secretaría Ejecutiva, disponibilidad y voto. Avance al cierre de ese lote: 114/142 candidatas; entonces quedaban 28 pendientes. Consulte [compatibilidad_transversal_lote_04_2026_es.md](compatibilidad_transversal_lote_04_2026_es.md). No se eliminan funciones de firma o corrección por la revocación puntual del archivo histórico.\n' if es else '24 notas de Secretaria Executiva, disponibilidade e voto. Avanço ao final desse lote: 114/142 candidatas; então restavam 28 pendentes. Consulte [compatibilidad_transversal_lote_04_2026_pt.md](compatibilidad_transversal_lote_04_2026_pt.md). A revogação pontual do arquivo histórico não elimina funções de assinatura ou correção.\n')
 report+='\n## '+('Siguiente trabajo' if es else 'Próximo trabalho')+'\n\n'+('Clasificación del rastreo concluida: 142/142 candidatas, 0 pendientes. Confirmar los siete grupos seleccionados en pendientes_confirmacion_documental_2026_es.md. El rastreo no agota las relaciones implícitas; no se declara compatibilidad global definitiva. La traducción y el examen de las 398 decisiones están completos; estos pendientes impiden declarar concluida la edición definitiva.\n' if es else 'Classificação do rastreio concluída: 142/142 candidatas, 0 pendentes. Confirmar os sete grupos selecionados em pendientes_confirmacion_documental_2026_pt.md. O rastreio não esgota relações implícitas; não se declara compatibilidade global definitiva. A tradução e o exame das 398 decisões estão completos; essas pendências impedem declarar concluída a edição definitiva.\n')
 (d/f'revision_editorial_consolidacion_2026_{lang}.md').write_text(report)
audit={**progress,'crossHistoricalCompatibilityProgress':c['metadata']['crossHistoricalCompatibilityProgress'],'documentaryConfirmationProgress':c['metadata']['documentaryConfirmationProgress'],'manualComparativeUnits':1774,'annexComparativePages':560,'sourceIntegrityChecks':'passed','sourceIssueSelection':[{'id':rid,'noteEs':es,'notePt':pt} for rid,es,pt in issues],'automaticSignalReviews':flagreviews,'correctionLedger':'correcciones_editoriales_consolidacion_2026.json'}
(d/'revision_editorial_consolidacion_2026.json').write_text(json.dumps(audit,ensure_ascii=False,indent=2)+'\n')
for name in progress['documents']+['revision_editorial_consolidacion_2026.json','correcciones_editoriales_consolidacion_2026.json']:shutil.copyfile(d/name,ROOT/'static/documentos'/name)
path.write_text(json.dumps(c,ensure_ascii=False));print('Suplementos: 398 decisiones por idioma; control editorial documentado.')
